<p class="intro">Your store at a glance. Start a sale or keep your catalog up to date.</p><div class="metrics"><?php foreach(['Total sales value'=>'₱'.number_format((float)$revenue,2),'Transactions'=>$count,'Active products'=>$products,'Customers'=>$customers] as $label=>$value): ?><article><span><?= esc($label) ?></span><strong><?= esc($value) ?></strong></article><?php endforeach ?></div>
